import React from 'react';
import { createCommand, createOption } from '@commander-js/extra-typings';
import type { AstroCommandServices } from '@wix/cli-command-contract';
import { CliError, CliErrorCode } from '@wix/cli-error';

export const finalizeMigrationCommand = (
  services: AstroCommandServices,
  cliVersion: string
) => {
  return createCommand('finalize-migration')
    .description(
      'Point the project at the accepted editor migration parent, then build and release it'
    )
    .addOption(
      createOption(
        '--app-id <app-id>',
        'Explicit parent app ID if migration lookup is unavailable'
      )
    )
    .addOption(
      createOption(
        '--site-id <site-id>',
        'Explicit parent site ID if migration lookup is unavailable'
      )
    )
    .action(async (options, command) => {
      const { runCommand } = await import('./render-command.js');
      const { FinalizeMigrationCommand } = await import(
        '../components/FinalizeMigrationCommand/index.js'
      );
      const { runWixCommand } = await import('../migration/run-wix-command.js');
      const { parseOperatorTarget, readEnvTarget } = await import(
        '../migration/parent-deployment-target.js'
      );

      await runCommand(command, services, cliVersion, async (model, render) => {
        if (services.definedWixConfig.config.projectType !== 'Site') {
          throw new CliError({
            code: CliErrorCode.FinalizeMigrationUnsupportedForProjectType(),
            cause: null,
          });
        }
        const operatorTarget = parseOperatorTarget(options);

        await runWixCommand('env', 'pull');

        const expected =
          operatorTarget ?? (await readEnvTarget(model.projectFolder));
        const inFlight: { publishing?: Promise<void> } = {};
        await render(
          <FinalizeMigrationCommand
            expected={expected}
            operatorTarget={operatorTarget}
            onPublishing={(publishing) => {
              inFlight.publishing = publishing;
            }}
          />
        );
        // Ctrl+C unmounts the UI while a step is still running. Wait for the
        // step, so it reports as canceled rather than the command succeeding.
        await inFlight.publishing;
      });
    });
};
